# A toy policy engine (PE) for admin sessions: every input must pass
def decide(req):
    reasons = []
    if req["device"] != "paw":
        reasons.append("not a privileged access workstation")
    if not req["phishing_resistant_mfa"]:
        reasons.append("MFA is not phishing-resistant")
    if req["target_tier"] == 0 and not req["jit_approved"]:
        reasons.append("no approved just-in-time request")
    if req["device_health"] != "compliant":
        reasons.append("device not compliant")
    return ("ALLOW", []) if not reasons else ("DENY", reasons)

base = {"device": "paw", "phishing_resistant_mfa": True, "target_tier": 0,
        "jit_approved": True, "device_health": "compliant"}
print(decide(base))
print(decide({**base, "device": "laptop"}))
print(decide({**base, "jit_approved": False, "phishing_resistant_mfa": False}))

# output:
# ('ALLOW', [])
# ('DENY', ['not a privileged access workstation'])
# ('DENY', ['MFA is not phishing-resistant', 'no approved just-in-time request'])
